import org.apache.commons.lang3.math.NumberUtils;
import java.math.BigDecimal;
import java.math.BigInteger;

public class Probe {
    public static void main(String[] args) throws Exception {
        probeCreateNumber("12.3");
        probeCreateNumber("12.3f");
        probeCreateNumber("12.3d");
        probeCreateNumber("0x80000000");
        probeCreateNumber("-0x80000000");
        probeCreateNumber("0xFFFFFFFF");
        probeCreateNumber("0xFFFFFFFFL");
        probeCreateNumber("3.14159265358979323846d"); // precise
        probeCreateNumber("2.5e300");
        probeCreateNumber("2.5e300f");
        probeCreateNumber("09");
        probeCreateNumber("0");
        probeCreateNumber("0.0");
        probeCreateNumber("-0");
        probeCreateNumber("017");
        probeCreateNumber("1L");
        probeCreateNumber("1l");
        probeCreateNumber("-1L");
        probeCreateNumber(String.valueOf(Long.MAX_VALUE));
        probeCreateNumber(String.valueOf(Long.MAX_VALUE) + "0"); // too big for long -> BigInteger
        probeCreateNumber("100000000000000000000L"); // too big for long with L suffix
        probeIsParsable(null);
        probeIsParsable("");
        probeIsParsable(" ");
        probeIsParsable("1L");
        probeIsParsable("NaN");
        probeIsParsable("Infinity");
        probeIsParsable("-Infinity");
        probeIsParsable("0x1p0");
        probeIsParsable(String.valueOf(Long.MIN_VALUE));
        System.out.println("isCreatable(\"09\")=" + NumberUtils.isCreatable("09"));
        System.out.println("isCreatable(null)=" + NumberUtils.isCreatable(null));
        System.out.println("isCreatable(\"\")=" + NumberUtils.isCreatable(""));
        System.out.println("isCreatable(\" \")=" + NumberUtils.isCreatable(" "));
        System.out.println("toScaledBigDecimal(null)=" + NumberUtils.toScaledBigDecimal((BigDecimal) null));
        System.out.println("toScaledBigDecimal(2.255)=" + NumberUtils.toScaledBigDecimal(new BigDecimal("2.255")));
        try {
            NumberUtils.max();
            System.out.println("max() empty array did not throw!");
        } catch (Exception e) {
            System.out.println("max() empty -> " + e.getClass().getSimpleName());
        }
        try {
            NumberUtils.max((int[]) null);
            System.out.println("max(null) did not throw!");
        } catch (Exception e) {
            System.out.println("max(null) -> " + e.getClass().getSimpleName());
        }
        try {
            BigInteger bi = NumberUtils.createBigInteger("--1");
            System.out.println("createBigInteger(--1) = " + bi);
        } catch (Exception e) {
            System.out.println("createBigInteger(--1) -> " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        try {
            BigInteger bi = NumberUtils.createBigInteger("0");
            System.out.println("createBigInteger(0) = " + bi);
        } catch (Exception e) {
            System.out.println("createBigInteger(0) -> " + e.getClass().getSimpleName());
        }
    }

    static void probeCreateNumber(String s) {
        try {
            Number n = NumberUtils.createNumber(s);
            System.out.println("createNumber(" + s + ") = " + n + " [" + n.getClass().getSimpleName() + "]");
        } catch (Exception e) {
            System.out.println("createNumber(" + s + ") -> " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
    }

    static void probeIsParsable(String s) {
        try {
            boolean b = NumberUtils.isParsable(s);
            System.out.println("isParsable(" + s + ") = " + b);
        } catch (Exception e) {
            System.out.println("isParsable(" + s + ") -> " + e.getClass().getSimpleName());
        }
    }
}

